//! Natural-language packs: a directory of data per language, and routing each word to the packs
//! for its script. See `docs/01-architecture.md` §4.
//!
//! Adding a language is a directory, not a diff: a pack is read from its `pack.toml` and the files
//! it names, and nothing here knows which language it is reading.

pub mod installed;
pub mod locale_path;
pub mod pack;
pub mod typos;
mod vocabulary;
mod word_list;

use std::path::Path;

use orthra_text::script::Script;

use crate::pack::{Pack, PackError};

#[cfg(test)]
mod tests;

/// Generated by `build.rs`: every pack under `packs/`, embedded.
mod builtin {
    include!(concat!(env!("OUT_DIR"), "/builtin.rs"));
}

/// The enabled packs.
#[derive(Debug)]
pub struct Packs {
    packs: Vec<Pack>,
}

impl Packs {
    /// The built-in packs for `tags`, in that order. A tag with no built-in pack is an error, not a
    /// pack quietly left out: a config that names a language should check it or say why not.
    pub fn builtin(tags: &[&str]) -> Result<Packs, PackError> {
        let mut shared = pack::Shared::default();
        let packs = tags
            .iter()
            .map(|tag| Pack::builtin_sharing(tag, &mut shared))
            .collect::<Result<_, _>>()?;
        Ok(Packs { packs })
    }

    /// The packs for `tags`, built in or installed under `packs`, and the tags of the installed
    /// ones that are not there yet, which check nothing until they are installed. A tag with no
    /// pack at all is still an error.
    pub fn load(tags: &[&str], packs: Option<&Path>) -> Result<(Packs, Vec<String>), PackError> {
        let mut shared = pack::Shared::default();
        let mut loaded = Vec::new();
        let mut missing = Vec::new();
        for tag in tags {
            match Pack::load_sharing(tag, packs, &mut shared)? {
                Some(pack) => loaded.push(pack),
                None => missing.push((*tag).to_owned()),
            }
        }
        Ok((Packs { packs: loaded }, missing))
    }

    /// The packs that can judge a word in `script`. None means the word is not checked: silence,
    /// deterministically, rather than every Cyrillic word reported in an English project.
    pub fn for_script(&self, script: Script) -> impl Iterator<Item = &Pack> {
        self.packs
            .iter()
            .filter(move |pack| pack.script() == script)
    }

    pub fn iter(&self) -> impl Iterator<Item = &Pack> {
        self.packs.iter()
    }

    /// Reads every pack's dictionaries now, rather than on the first word of its script.
    pub fn read_dictionaries(&self) {
        for pack in &self.packs {
            pack.read_dictionaries();
        }
    }

    /// Every enabled pack's labels for a line that names people, lower-cased: `author`.
    pub fn name_labels(&self) -> Vec<Box<str>> {
        self.union(|pack| pack.name_labels())
    }

    /// The words every enabled pack gives that start a comment line naming people: `copyright`.
    pub fn name_lines(&self) -> Vec<Box<str>> {
        self.union(|pack| pack.name_lines())
    }

    fn union(&self, of: impl Fn(&Pack) -> &[Box<str>]) -> Vec<Box<str>> {
        let mut all: Vec<Box<str>> = self
            .packs
            .iter()
            .flat_map(|pack| of(pack).iter().cloned())
            .collect();
        all.sort_unstable();
        all.dedup();
        all
    }

    /// Every character an enabled pack treats as inside a word, with the script of the words it is
    /// inside: uk-UA's hyphen joins `будь-який`, and joins no Latin words. Joining them for every
    /// script made `codebook-lsp` one unknown word once uk-UA was enabled (2026-11-06).
    pub fn word_internal(&self) -> Vec<(char, Script)> {
        let mut chars: Vec<(char, Script)> = self
            .packs
            .iter()
            .flat_map(|pack| pack.word_internal().iter().map(|c| (*c, pack.script())))
            .collect();
        chars.sort_unstable();
        chars.dedup();
        chars
    }
}
